import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.DGk0zlJw.js";const g=JSON.parse('{"title":"Beacon 需求实现差距分析（2026-10-24）","description":"","frontmatter":{},"headers":[],"relativePath":"review/2026-10-24-beacon-requirement-gap.md","filePath":"review/2026-10-24-beacon-requirement-gap.md"}'),r={name:"review/2026-10-24-beacon-requirement-gap.md"};function a(s,d,n,i,l,p){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="beacon-需求实现差距分析-2026-10-24" tabindex="-1">Beacon 需求实现差距分析（2026-10-24） <a class="header-anchor" href="#beacon-需求实现差距分析-2026-10-24" aria-label="Permalink to &quot;Beacon 需求实现差距分析（2026-10-24）&quot;">​</a></h1><p>审计基线：本地 <code>main</code>，HEAD <code>8d16605</code>。仅静态读码及文档溯源；未运行 Windows/WinUI，不把源码存在当作用户已能看到，也不把潜在裁切当作实测缺陷。本次只新增本报告。</p><p>结论：已有全局两种样式和实例级五种模板，不能说实现完全写死；但选择、保存、恢复与预览没有形成可靠闭环。共列 <strong>13 条差距：11 条源码可确认的行为/文档契约差距，2 条待体验验证的入口与可见性问题</strong>。最关键的是无状态组件进入错误模式，无法应用样式（G01）。</p><h2 id="_1-原始需求溯源与证据层级" tabindex="-1">1. 原始需求溯源与证据层级 <a class="header-anchor" href="#_1-原始需求溯源与证据层级" aria-label="Permalink to &quot;1. 原始需求溯源与证据层级&quot;">​</a></h2><p>本次用户原话：「展示的方式可以选择, 到现在展示组件的中心都看不到」。这是本次会话直接输入；仓内此前未找到该完整句子的原始记录。<strong>“中心”的确切对象及其验收定义，需求原文缺失</strong>。不能擅自把它定为组件中心页面、圆环中心数字、画布中心点或焦点。</p><p><code>docs/requirements</code> 目录不存在。检索覆盖 <code>todo.md</code>、README 双语、<code>docs/design</code> 及 <code>docs/zh/design</code>、<code>docs/review</code>、本地 issue 清单、<code>.github</code> 和 Git 提交说明；忽略依赖与构建产物。根目录部分英文文档只是占位页（如 <code>docs/design/redesign-plan-2026-10-16.md:4</code>），故追到中文正文。未查询远端 GitHub issue，不能据本地无记录断言远端也无需求。</p><p>以下逐条摘录与本题直接相关的原文；“用户令转录”“外部建议”“实现台账”分开看，后两者不冒充用户原话。</p><table tabindex="0"><thead><tr><th>ID / 性质</th><th>需求或记录原文</th><th>出处</th></tr></thead><tbody><tr><td>R01 用户令转录</td><td>「beacon 能选择展示的组件最好」</td><td><code>docs/design/collapsed-progress.md:254</code>；中文同文 <code>docs/zh/design/collapsed-progress.md:254</code></td></tr><tr><td>R02 用户令转录（代码注释）</td><td>「设置里让用户自己选表现方式，比如一开始的进度条」</td><td><code>src/Beacon.App/Windows/SettingsWindow.cs:1218</code>（标注 2026-10-10；未找到独立会话原稿）</td></tr><tr><td>R03 设计细化</td><td>「L0 tile 的 <code>bar|pool</code> 是<strong>样式二选一</strong>不是有无」</td><td><code>docs/zh/design/collapsed-progress.md:282</code></td></tr><tr><td>R04 设计细化</td><td>「<strong>重启不丢</strong> = config.json 落盘即满足，无额外机制。」</td><td><code>docs/zh/design/collapsed-progress.md:313</code>（此处说偏好开关，不直接等同模板身份存储）</td></tr><tr><td>R05 外部设计稿</td><td>「同一份数据可以被不同类型的组件展示。」</td><td><code>docs/zh/design/redesign-plan-2026-10-16.md:822</code></td></tr><tr><td>R06 外部设计稿</td><td>「一个显示实例可以组合多个数据源。」</td><td><code>docs/zh/design/redesign-plan-2026-10-16.md:823</code></td></tr><tr><td>R07 外部设计稿</td><td>「应为组件库建立独立的视觉示例页，集中展示组件在不同状态和尺寸下的实际效果。」</td><td><code>docs/zh/design/redesign-plan-2026-10-16.md:258</code></td></tr><tr><td>R08 外部设计稿</td><td>「默认尺寸和最小尺寸。」「可访问性名称与键盘操作。」「在小尺寸下如何降级展示。」</td><td><code>docs/zh/design/redesign-plan-2026-10-16.md:233</code>、<code>:237</code>、<code>:239</code></td></tr><tr><td>R09 外部评审建议</td><td>「选择已有数据 选择展示样式 实时预览 应用」</td><td><code>docs/review/review-2026-10-18-component-center.md:62</code></td></tr><tr><td>R10 外部评审建议</td><td>「展示中心应默认使用当前 Widget 的真实状态预览，允许用户调整标题、颜色、尺寸等外观参数。」</td><td><code>docs/review/review-2026-10-18-component-center.md:98</code></td></tr><tr><td>R11 外部评审验收建议</td><td>「一份百分比数据至少可选择横条、圆环、数字卡和水位样式」</td><td><code>docs/review/review-2026-10-18-component-center.md:113</code></td></tr><tr><td>R12 外部评审验收建议</td><td>「GLM 使用横条、DeepSeek 使用圆环，互不影响」；「相同数据在不同展示位置可以不同布局」</td><td><code>docs/review/review-2026-10-18-component-center.md:115</code>、<code>:116</code></td></tr><tr><td>R13 外部评审对用户意图的转述</td><td>「同一个百分比数据，可以在界面中自主选择数字、横条、圆环、水位等适用的展示方式，选择不会改变数据源，也不会要求用户编写组件 JSON。」</td><td><code>docs/review/2026-10-22-display-component-selection.md:256</code></td></tr><tr><td>R14 实施台账</td><td>「组件示例页（SampleGalleryWindow）改造为组件中心『选 → 调 → 用』单一闭环」</td><td><code>todo.md:26</code>（原文使用中文双引号；此处引号转排）</td></tr><tr><td>R15 实施台账</td><td>「组件中心定向模式改模板选择（左列按数据能力筛选的样式列表 + 应用面 tile/row/detail 可选，应用按面合并其余面保留）」</td><td><code>todo.md:28</code></td></tr><tr><td>R16 未完成工作约束</td><td>「在跟踪表 12 项清零前不新增展示模板种类。」</td><td><code>todo.md:133</code>；十二项均未开工见 <code>docs/review/2026-10-22-display-component-selection.md:268</code>、<code>:272</code>–<code>:283</code></td></tr><tr><td>R17 README 定位</td><td>「持续从不同数据源取数，标准化为一份共享状态，交给显示组件呈现」</td><td><code>README.zh.md:21</code>；仅产品定位，没有样式选择或“中心”的验收定义</td></tr><tr><td>R18 本地 issue 痕迹 B-702</td><td>「消费 B-602 落库的 pinned 标记 + Settings 逐个开关；PinTile（StatusLight+标签+数字/进度，32 DIP 高）；仅 pinSupported 类型可钉；pins.json 读写。」</td><td><code>docs/zh/mvp-issues.md:337</code>；是显示/钉选基础，不等于展示方式切换</td></tr><tr><td>R19 特定场景的中心要求</td><td>「是 logo 本体居中、进度环作 logo 的外圈。」</td><td><code>docs/zh/design/collapsed-progress.md:15</code>；仅适用于坍缩徽章，不能外推为所有圆环中心必须有数字</td></tr></tbody></table><p>Git 痕迹：<code>184cdae</code> 引入 10-22 外部评审；<code>todo.md:27</code> 记录 P0 <code>4847f99</code>，<code>:28</code> 记录 P1 <code>94aa2aa+32dbe97+fb10bd1</code>。这些是演进线索，不代表本次验收通过。10-18 的旧“无绑定/无模板”结论已过时，不能照抄为当前缺陷。</p><h2 id="_2-展示组件真实实现与-中心-现状" tabindex="-1">2. 展示组件真实实现与“中心”现状 <a class="header-anchor" href="#_2-展示组件真实实现与-中心-现状" aria-label="Permalink to &quot;2. 展示组件真实实现与“中心”现状&quot;">​</a></h2><h3 id="展示方式与切换链" tabindex="-1">展示方式与切换链 <a class="header-anchor" href="#展示方式与切换链" aria-label="Permalink to &quot;展示方式与切换链&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>当前实现与可选项</th><th>源码证据</th></tr></thead><tbody><tr><td>全局传统额度外观</td><td>ComboBox 两种：bar 进度条（默认）、pool 圆池注水；用户可选并保存</td><td><code>src/Beacon.App/Windows/SettingsWindow.cs:1221</code>、<code>:1246</code>、<code>:1343</code></td></tr><tr><td>实例展示模板</td><td>五种：bar 横条、ring 圆环、number 数字卡、pool 水位、statusline 状态行</td><td><code>src/Beacon.Core/Services/DisplayTemplates.cs:22</code>–<code>:38</code></td></tr><tr><td>兼容筛选</td><td>当前 Progress 有值时五种均列出；没有进度时仅状态行。null 状态另触发 UI 模式错误（G01）</td><td><code>src/Beacon.Core/Services/DisplayTemplates.cs:43</code>；<code>src/Beacon.App/Windows/SampleGalleryWindow.cs:198</code></td></tr><tr><td>选择操作</td><td>设置“组件”行的“展示样式”→独立窗口→左侧列表点击换模板→右侧选 tile/row/detail→“应用展示样式”</td><td><code>src/Beacon.App/Windows/SettingsWindow.cs:2830</code>；<code>src/Beacon.App/Windows/SampleGalleryWindow.cs:322</code>、<code>:499</code>、<code>:614</code></td></tr><tr><td>保存与刷新</td><td>校验树，替换所选 surface 根树，UpsertWidget 落盘；PinsChanged 发刷新通知。数据源 ID 沿用</td><td><code>src/Beacon.App/Windows/SettingsWindow.cs:2702</code>、<code>:2760</code></td></tr><tr><td>通用组件中心</td><td>关于区“组件中心”进入基础类型目录及 Props 表单；应用需先有树编辑目标、再回设置保存。不是直接选择某数据的成品展示模板</td><td><code>src/Beacon.App/Windows/SettingsWindow.cs:702</code>、<code>:2727</code>；<code>src/Beacon.App/Windows/SampleGalleryWindow.cs:46</code>、<code>:370</code></td></tr><tr><td>正式渲染</td><td>模板生成绑定树→ComponentSurfaceRenderer 工厂；tile 用 PinTile（定义在 PinnedHostWindow.cs），详情用 DetailWindow</td><td><code>src/Beacon.App/Components/ComponentSurfaceRenderer.cs:125</code>、<code>:270</code>、<code>:301</code>、<code>:329</code>；<code>src/Beacon.App/Windows/PinnedHostWindow.cs:216</code>；<code>src/Beacon.App/Windows/DetailWindow.cs:194</code></td></tr></tbody></table><p>所以：<strong>切换机制确实存在，并非写死一种；但模板结构/尺寸是预设值，普通定向模式没有外观参数表单。</strong> “基础组件类型数”“成品模板数”“全局旧样式数”不可混算。</p><h3 id="中心-分别核查-不替用户决定含义" tabindex="-1">“中心”分别核查，不替用户决定含义 <a class="header-anchor" href="#中心-分别核查-不替用户决定含义" aria-label="Permalink to &quot;“中心”分别核查，不替用户决定含义&quot;">​</a></h3><ol><li><strong>组件中心功能入口</strong>：代码存在两个入口，关于页叫“组件中心”，实例行叫“展示样式”（SettingsWindow.cs:702、:2830）。关于页打开的却是基础工具箱，实际同数据样式选择要走另一个入口。可达路径存在，命名和用途容易错位；用户当前安装版本是否包含这些提交、是否实际可见，未验证。</li><li><strong>窗口中央内容区</strong>：SampleGalleryWindow.cs:173 建五列 Grid，中列 300 DIP，预览加在第 2 列（:223、:270）；有“预览”标题、Border 和内部 ScrollViewer（:233）。不是没有中央区域，也没有设置该区域 Collapsed。但窗口宽 860 DIP、最高 780 DIP（:30、:157），根 Grid 无整体滚动；预览仅纵向滚动，横向禁用（:244）。小屏、高 DPI、窗口遮挡和缩小时的完整可达性不能由代码保证，需实机检查。</li><li><strong>圆环几何中心/中心内容</strong>：ComponentSurfaceRenderer.cs:301 的 Ring 仅向 Grid 加两个 Ellipse，没有中心 TextBlock/图标；DisplayTemplates.cs:27 把摘要作为圆环旁的兄弟节点。故中心空白是结构事实，不是中心数字被遮住。仓内没有通用圆环必须显示中心数字的明确要求；坍缩 logo 居中要求 R19 属另一场景。</li><li><strong>中心点、中轴、画布回中</strong>：本条选择器是普通 Grid/ListView 窗口，不是带平移缩放的画布（SampleGalleryWindow.cs:171）。未找到本功能的中心标记、适应视图/回中需求，不能凭用户一句话补成画布需求。</li><li><strong>键盘焦点</strong>：列表、按钮、ComboBox 是标准控件；有点击事件不等于完整键盘验收。中心预览里的 Ellipse 也不是交互目标。未执行 Tab/Enter/Space、焦点环或读屏验证，不能宣称全部可达。</li></ol><h2 id="_3-需求—现状—差距-13-条" tabindex="-1">3. 需求—现状—差距（13 条） <a class="header-anchor" href="#_3-需求—现状—差距-13-条" aria-label="Permalink to &quot;3. 需求—现状—差距（13 条）&quot;">​</a></h2><p>下列文件名以第二节源码路径为准；每条给出需求和实现定位。G01–G11 是静态确认的行为或既有文档契约差距；G12–G13 是待验证项，不能计为已经实测的 UI bug。外部评审建议作为仓内目标线索，不等于用户已逐项确认。</p><table tabindex="0"><thead><tr><th>ID</th><th>需求/目标出处</th><th>当前代码事实</th><th>差距、影响与验收方向</th></tr></thead><tbody><tr><td>G01 最高优先</td><td>R09；10-22 评审 <code>:272</code> 空状态可配置</td><td>SettingsWindow.cs:2747 取状态，:2751 将通用回调设 null；SampleGalleryWindow.cs:198 用状态是否 null 判断模式，:627 无通用回调就报错</td><td>新建/首次未取数时点击展示样式却进入工具箱，无法应用。应按目标实例而非状态有无确定模式；无数据也能选兼容配置并保存</td></tr><tr><td>G02</td><td>R12/R15；评审 <code>:273</code></td><td>SettingsWindow.cs:2753 闭包捕获旧 widget；:2768 从该对象复制各面</td><td>同一选择器先保存 tile 再保存 row，第二次以旧 Components 合并，可能丢失第一次修改。应用时读最新配置并验证连续双面保存</td></tr><tr><td>G03</td><td>R11 数字卡可用；评审 <code>:274</code></td><td>DisplayTemplates.cs:31 unit=%；ComponentBindingEngine.cs:35 已返回带 % 的值；ComponentMetric.cs:33 另画单位</td><td>52% 后又显示一个 %（两个 TextBlock），数字卡重复单位；验收 0/52/100/缺失四态</td></tr><tr><td>G04</td><td>R12；评审 <code>:275</code> 样式恢复</td><td>SampleGalleryWindow.cs:146 恒选兼容首项，:122 面默认 tile；构造器 :136 未接收当前配置</td><td>已保存圆环再打开却选横条；选择器不能准确表示当前样式/面。需保存身份或可靠反解并恢复</td></tr><tr><td>G05</td><td>R13；评审 <code>:120</code>、<code>:276</code> 槽位替换</td><td>SettingsWindow.cs:2772 整面替换；PinnedHostWindow.cs:212 有树就跳过传统六列</td><td>普通换样式同时移除原品牌/标签等外围结构，超出只换数据呈现的预期。应保留外围，只换明确槽位；整树替换标为高级操作</td></tr><tr><td>G06</td><td>R05；评审 <code>:277</code>–<code>:278</code> 能力匹配</td><td>DisplayTemplates.cs:20 仅 RequiresProgress；:43 用当前 Progress.HasValue，模板无语义/单位/适用面声明</td><td>“这次没值”被等同“不支持进度”；适用性不区分来源语义和展示空间。需稳定能力描述与不可用原因</td></tr><tr><td>G07</td><td>R08 状态规范；评审 <code>:279</code></td><td>ComponentSurfaceRenderer.cs:285 绑定缺失回退 Props.progress，默认 0</td><td>缺失进度和有效 0 画成同一形态；需无数据/过期/有效零区别，不能伪装确定零值</td></tr><tr><td>G08</td><td>R06；评审 <code>:280</code></td><td>DetailWindow.cs:199 仅传自身 _state，未走完整 sources 映射重载；映射重载在 ComponentSurfaceRenderer.cs:161</td><td>详情组合多源绑定缺少真实附加源输入；需映射及附加源更新链验收</td></tr><tr><td>G09</td><td>R09/R10；评审 <code>:281</code></td><td>SampleGalleryWindow.cs:117 readonly 快照，:145 赋值，:604 预览复用；:359 定向表单只有说明与 surface</td><td>“实时预览”不跟随后续数据更新，且不能调标题/颜色/尺寸。参数变化重新渲染不等于状态实时；应接更新并提供参数表单</td></tr><tr><td>G10</td><td>R03/R12；评审 <code>:283</code></td><td>SettingsWindow.cs:1221 全局外观仍可选；PinnedHostWindow.cs:216 声明式分支提前返回</td><td>实例树实际优先于旧全局样式，但界面未在全局选项处说明作用范围，用户可能保存后看不到变化。需清楚标注优先级及恢复默认入口</td></tr><tr><td>G11</td><td>R07；R16；<code>todo.md:28</code></td><td>SampleGalleryWindow.cs:604 固定样例/快照、:233 单一预览盒；未提供多状态多尺寸验证矩阵</td><td>示例页存在不等于完成“不同状态和尺寸”验收；台账仍写端到端观感待装机。需对五模板三展示面保存、重开及状态变化给出证据</td></tr><tr><td>G12 待用户确认/体验验证</td><td>本次“中心都看不到”；R09</td><td>SettingsWindow.cs:702 关于区中心，:2830 行内展示样式；两路径用途不同</td><td>入口发现与命名错位风险明确，是否正是用户所指尚不明。建议统一实例编辑入口和标题，在实机验证用户能直接找到</td></tr><tr><td>G13 待 Windows 实测</td><td>R08；评审 <code>:282</code></td><td>PinnedHostWindow.cs:204 固定 tile 高；DisplayTemplates.cs:30 数字卡纵排大字+摘要、:26 横条宽 220；SampleGalleryWindow.cs:30 固定窗宽</td><td>预览与真实宿主尺寸不同，存在裁切/中心内容不可达风险，尚无本次截图证明。需小尺寸、长文本及多 DPI 验证，不先断言中心已被裁掉</td></tr></tbody></table><p>没有把 R19 的坍缩 logo 居中要求误记为通用圆环缺陷，也没有把过去“模板没有绑定”的旧问题再次计入。相比旧台账十二项，本表合并“语义描述+能力匹配”为 G06，将入口发现与状态/尺寸验收单列；不是机械搬运旧计数。</p><h2 id="_4-交互形态建议-建议-不追认成历史需求" tabindex="-1">4. 交互形态建议（建议，不追认成历史需求） <a class="header-anchor" href="#_4-交互形态建议-建议-不追认成历史需求" aria-label="Permalink to &quot;4. 交互形态建议（建议，不追认成历史需求）&quot;">​</a></h2><p>成熟可视化编辑器的可借鉴模式：Grafana 在面板编辑器提供可视化类型选择、预览、显示选项，并明确保存/放弃操作；面板本身有 Edit 入口。参见 <a href="https://grafana.com/docs/grafana/latest/visualizations/panels-visualizations/panel-editor-overview/" target="_blank" rel="noreferrer">Grafana Panel editor</a> 与 <a href="https://grafana.com/docs/grafana/latest/visualizations/panels-visualizations/panel-overview/" target="_blank" rel="noreferrer">Panel overview</a>，检索日期 2026-10-24。以下是对 Beacon 的适配建议，不是这些产品的逐项原样行为：</p><ul><li>每个数据实例提供可发现的“展示方式”入口；统一进入“实例名 / 展示面 / 当前样式”的编辑器。“组件中心”用于浏览模板时，也应明确选择目标实例，基础控件工具箱放高级区。</li><li>左侧用带缩略预览的单选模板列表，中间在真实宿主尺寸内预览，右侧提供样式参数；选项显示选中态和不兼容原因。样式选择保持数据源不变，不要求用户编辑 JSON。</li><li>用“应用 / 取消（放弃未保存修改）”，已应用有明确反馈，重开恢复当前项；不同实例和不同 surface 独立保存。无状态时显示“等待数据”并允许合适配置，不能跳到另一个模式。</li><li>预览随数据更新，注明最新时间；提供缺失、零值、正常、错误、过期的检查方式，并允许查看目标实际尺寸。超过可用空间要滚动或响应式布局。</li><li>若“中心”确认为画布中心，再考虑“适应内容/回到选中对象”等画布交互；若指圆环读数，再设计中心文字及尺寸规则。当前阶段不以此为由新增画布或中心数字功能。</li></ul><h2 id="_5-需求原文缺失部分-供用户确认的可验收清单" tabindex="-1">5. 需求原文缺失部分：供用户确认的可验收清单 <a class="header-anchor" href="#_5-需求原文缺失部分-供用户确认的可验收清单" aria-label="Permalink to &quot;5. 需求原文缺失部分：供用户确认的可验收清单&quot;">​</a></h2><p>下列是把本次话语拆成候选验收点，不表示用户已经确认扩展范围。阻塞的是语义确认，不影响本报告完成。</p><table tabindex="0"><thead><tr><th>候选</th><th>可观察的验收方式</th><th>尚待确认的边界</th></tr></thead><tbody><tr><td>A1 方式可选择</td><td>在同一数据实例上找到“展示方式”，选择至少两种适用方式，应用后实际 UI 改变</td><td>是实例级还是全局；需要哪些具体样式？现有五模板只是候选基线</td></tr><tr><td>A2 选择有效且可恢复</td><td>不改连接/数据源，保存后重开和重启仍体现所选样式</td><td>是否包括 tile、row、detail 全部面，以及每面独立？</td></tr><tr><td>A3 中心可见可达</td><td>在指定屏幕、DPI、窗口状态下看到并能到达用户所指对象</td><td>“中心”究竟是组件中心入口、预览主体、圆环中心内容、坍缩 logo、几何中心/中轴还是键盘焦点？应先指定对象，不能全部默认实现</td></tr><tr><td>A4 无数据也不误导</td><td>新建/离线打开选择器，清楚显示数据状态；不陷入不能应用的无关编辑模式</td><td>无数据时允许预选所有已知能力还是限制部分方式？</td></tr><tr><td>A5 可复核证据</td><td>用用户正在使用的安装版本走完“找到→选择→预览→应用→重开”，截图标出中心对象</td><td>需 Windows 构建版本、复现场景和用户确认后的中心定义</td></tr></tbody></table><p>后续验收至少覆盖：同一窗连续保存两面、重开恢复选择、两实例互不影响、进度 0/52/100/缺失、数据 52→78 更新、窗口缩小/高 DPI、键盘进入选择并应用。当前未做这些运行验证，不用单元测试通过替代可见可达证据。</p><h2 id="_6-交付与范围" tabindex="-1">6. 交付与范围 <a class="header-anchor" href="#_6-交付与范围" aria-label="Permalink to &quot;6. 交付与范围&quot;">​</a></h2><p>仅新增此报告，不修改实现代码。启动时工作区已有未跟踪 <code>docs/.vitepress/config.mts</code>、<code>docs/package.json</code>、<code>docs/node_modules</code>，不属于本次差距分析，提交只应包含本报告。提交前检查引用存在、差距计数及 <code>git diff --check</code>。推送结果以执行日志和最终回报为准，不在报告预写成功。</p>',28)])])}const m=t(r,[["render",a]]);export{g as __pageData,m as default};
